	if sub, err := host.HostFromEnvVar(env); err != nil {
		return nil, err
	} else if sub != nil {
		result.Endpoint = sub
	}
	if val, ok := env["PROTO_SERVICES_TIMEDB_TIME_DB_NODE_STARTED_AT_MS"]; ok && val != "" {
		parsed, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return nil, err
		}
		result.StartedAtMs = parsed
	}
	if val, ok := env["PROTO_SERVICES_TIMEDB_TIME_DB_NODE_TRACE_ID"]; ok && val != "" {
		result.TraceId = val
	}
	if val, ok := env["PROTO_SERVICES_TIMEDB_TIME_DB_NODE_NOOP"]; ok && val != "" {
		parsed, err := strconv.ParseBool(val)
		if err != nil {
			return nil, err
		}
		result.Noop = parsed
	}
	return result, nil
